714	/**
715	 * Turns a stored preference into the channels one notification will use.
716	 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
717	 * the email channel additionally requires the org's `digest_email` plan flag.
718	 */
719	export function resolveChannels(
720	  preference: NotificationPreference | null,
721	  flags: FlagContext,
722	): readonly NotificationChannel[] {
723	  if (preference === null) return DEFAULT_CHANNELS;
724	
725	  const channels: NotificationChannel[] = [];
726	  if (preference.inApp) channels.push("in_app");
727	
728	  const emailAllowed =
729	    preference.email &&
730	    (!preference.digestOnly || isEnabled("digest_email", flags));
731	
732	  if (emailAllowed) channels.push("email");
733	  return channels;
734	}
