853	 */
854	export async function createComment(
855	  actor: Actor,
856	  input: CreateCommentInput,
857	): Promise<Comment> {
858	  assertOrgScope(actor, input.orgId);
859	
860	  const issue = requireFound(
861	    await issueRepo.findIssueById(input.orgId, input.issueId),
