979	/**
980	 * Union of the ids the client already resolved (optimistic UI) and the ones
981	 * parsed out of the body server-side. The server list wins on disagreement.
982	 */
983	async function resolveMentionedUsers(
984	  orgId: OrgId,
985	  body: string,
986	  clientProvided: readonly UserId[],
987	): Promise<readonly UserId[]> {
988	  const members = await memberRepo.listMembers({
989	    orgId,
990	    limit: MENTION_LOOKUP_LIMIT,
991	    cursor: null,
992	  });
993	
994	  const resolved = resolveMentions(body, members.items);
995	  const known = new Set(members.items.map((member) => member.userId));
996	
997	  return [
998	    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
999	  ];
1000	}
1001	/**
1002	 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
1003	 *
1004	 * Must call (do not reimplement): emit, shouldFilterArchived
1005	 */
1006	import { emit } from "@/lib/event-bus";
1007	import { createLogger } from "@/lib/logger";
1008	import { shouldFilterArchived } from "@/lib/soft-delete";
1009	import * as issueRepo from "@/server/repositories/issue-repository";
1010	import * as usageRepo from "@/server/repositories/usage-repository";
1011	import { toIsoTimestamp } from "@/types/common";
1012	import { runJob } from "./types";
1013	import type { JobResult } from "@/server/jobs/types";
1014	
1015	/** How many organizations one pass sweeps. */
1016	const ORG_BATCH = 50;
1017	
1018	/** Archived issues are never overdue — an archived issue has no due date. */
1019	const LIVE_ONLY = {} as const;
1020	
1021	const logger = createLogger("overdue-issue-job");
1022	
1023	/**
1024	 * Issues already announced this process's lifetime. A later sweep still
1025	 * finds a still-open, still-overdue issue — this is what keeps the job from
1026	 * re-emitting `issue.overdue` for it on every pass.
1027	 */
1028	const reported = new Set<string>();
1029	
1030	/** Test-only: clears the reported set so a fresh scenario starts empty. */
1031	export function resetOverdueTracking(): void {
1032	  reported.clear();
1033	}
1034	
1035	/**
1036	 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
1037	 * no notification logic: it announces the fact, and whoever cares (in-app
1038	 * alerts, the digest, webhooks) reacts on the bus.
1039	 */
1040	export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
1041	  return runJob("overdue-issues", async (result) => {
1042	    if (!shouldFilterArchived(LIVE_ONLY)) {
1043	      logger.warn("archive scope misconfigured; skipping sweep", {});
1044	      return;
1045	    }
1046	
1047	    const stamp = toIsoTimestamp(now);
1048	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
1049	
1050	    for (const orgId of orgIds) {
1051	      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);
1052	
1053	      for (const issue of overdue) {
1054	        if (issue.dueAt === null) continue;
1055	        if (reported.has(issue.id)) continue;
1056	
1057	        try {
1058	          await emit("issue.overdue", {
1059	            orgId,
1060	            actorId: null,
1061	            occurredAt: stamp,
1062	            issueId: issue.id,
1063	            projectId: issue.projectId,
1064	            dueAt: issue.dueAt,
1065	            assigneeId: issue.assigneeId,
1066	          });
1067	          reported.add(issue.id);
1068	          result.processed += 1;
1069	        } catch (error) {
1070	          result.failed += 1;
1071	          logger.error("failed to announce overdue issue", {
1072	            issueId: issue.id,
1073	            reason: error instanceof Error ? error.message : String(error),
1074	          });
1075	        }
1076	      }
1077	    }
1078	  });
1079	}
