open(p,'a').write('''
async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active" || member.archivedAt !== null) {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

/**
 * Marks a member away for `[startsAt, endsAt)`, replacing any earlier absence.
 * Members manage their own; managing someone else's takes the same right as
 * changing their role.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  if (input.userId !== actor.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  if (!(Date.parse(input.endsAt) > Date.parse(input.startsAt))) {
    throw new Error("An absence must end after it starts");
  }

  const delegateUserId = input.delegateUserId ?? null;
  if (delegateUserId !== null) {
    if (delegateUserId === input.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return memberRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note ?? null,
  });
}

export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  if (userId !== actor.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  await memberRepo.deleteAbsence(orgId, userId);
}

/** The stored absence until it has ended; a scheduled one is returned too. */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  await requireActiveMember(orgId, userId);

  const absence = await memberRepo.findAbsence(orgId, userId);
  if (absence === null) return null;
  return Date.now() < Date.parse(absence.endsAt) ? absence : null;
}

/**
 * The stand-in for `userId` at instant `at`: the delegate of an absence whose
 * window contains `at`, provided that delegate is still an active member.
 * `null` when the member is not away or has nobody standing in. Never chained —
 * the delegate's own absence is deliberately not consulted.
 */
export async function findActiveDelegate(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (absence === null || absence.delegateUserId === null) return null;

  const instant = at.getTime();
  if (
    !(instant >= Date.parse(absence.startsAt)) ||
    !(instant < Date.parse(absence.endsAt))
  ) {
    return null;
  }

  const owner = await memberRepo.findMember(orgId, userId);
  if (!owner || owner.status !== "active") return null;

  const delegate = await memberRepo.findMember(orgId, absence.delegateUserId);
  if (!delegate || delegate.status !== "active") return null;

  return absence.delegateUserId;
}
''')

