import { afterAll, beforeAll, expect, it } from "vitest";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as memberService from "@/server/services/member-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { listNotifications } from "@/server/services/notification-service";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, UserId } from "@/types/common";

let cleanup: () => void; let t: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); t = await createTenant("abs"); await usageRepo.recomputeUsage(t.org.id); });
afterAll(() => cleanup());
const iso = (ms: number) => new Date(Date.now() + ms).toISOString() as IsoTimestamp;
const notes = async (u: UserId, kind: any) => (await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: u, unreadOnly: false, kind: [kind], limit: 25, cursor: null })).items;

it("works", async () => {
  await memberService.setAbsence(t.actors.member, { orgId: t.org.id, userId: t.userIds.member, delegateUserId: t.userIds.admin, startsAt: iso(-1000), endsAt: iso(100000), note: null });
  const own = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Own one", assigneeId: t.userIds.member, dueAt: iso(-5000) }));
  expect(own.assigneeId).toBe(t.userIds.member);
  await runOverdueIssueJob(new Date());
  expect(await notes(t.userIds.admin, "issue_overdue")).toHaveLength(1);
  expect(await notes(t.userIds.member, "issue_overdue")).toHaveLength(0);

  await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: own.id, body: "hi", parentId: null, mentionedUserIds: [t.userIds.member, t.userIds.admin] } as any);
  expect(await notes(t.userIds.admin, "comment_mention")).toHaveLength(1);
  expect(await notes(t.userIds.member, "comment_mention")).toHaveLength(1);

  const adminMember = (await memberRepo.findMember(t.org.id, t.userIds.admin))!;
  await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: adminMember.id });
  expect((await memberService.getAbsence(t.actors.owner, t.org.id, t.userIds.member))?.delegateUserId).toBeNull();
  await memberService.clearAbsence(t.actors.owner, t.org.id, t.userIds.member);
  await memberService.clearAbsence(t.actors.member, t.org.id, t.userIds.member);
  expect(await memberService.getAbsence(t.actors.owner, t.org.id, t.userIds.member)).toBeNull();
});
EOF
